class TreeNode:
    "A named tree node containing optional value, children, and metadata"
    def __init__(self, name: str, children=None, value=None, **meta):
        if not isinstance(name, str): raise TypeError("name must be a str")
        if '/' in name: raise ValueError("name cannot contain '/'")
        children = list(children or [])
        if not all(isinstance(o, TreeNode) for o in children): raise TypeError("children must be TreeNodes")
        ns = [o.name for o in children]
        if len(ns) != len(set(ns)): raise ValueError("sibling names must be unique")
        self.name,self.children,self.value,self.meta = name,children,value,AD(meta)

    def __iter__(self): return iter(self.children)
    def __len__(self): return len(self.children)
    def __contains__(self, name): return any(o.name==name for o in self.children)
    def __eq__(self, o): return isinstance(o, TreeNode) and self.name==o.name and self.value==o.value and self.children==o.children and self.meta==o.meta
    def __repr__(self):
        a = ', '.join(filter(None, (
                f"{self.name!r}",
                '' if not self.children else f"{self.children!r}", 
                '' if self.value is None else f"{self.value!r}", 
                '' if not self.meta else f"**{dict(self.meta)!r}",
            )))
        return f"TreeNode({a})"

    def is_leaf(self): return not self.children

is_tree = lambda o: isinstance(o, TreeNode)


