@patch
def idx(self:TreeNode, name: str):
    "Index of direct child by name"
    for i,o in enumerate(self.children):
        if o.name == name: return i
    raise KeyError(name)

def _path_join(p, nm):
    if not nm: return p or '/'
    return f"/{nm}" if p in ('', '/') else f"{p}/{nm}"

def child(o: TreeNode, name: str):
    "Find direct child by name"
    for c in o.children:
        if c.name == name: return c
    raise KeyError(name)

@patch
def path(self:TreeNode, parent=''): return _path_join(parent, self.name)

@patch
def __getitem__(self:TreeNode, path):
    if isinstance(path, str):
        parts = [p for p in path.split('/') if p]
        o = self
        for p in parts: o = child(o, p)
        return o
    raise TypeError("path must be a str")

# %% ../nbs/01_tree.ipynb #0fcc03b2
def _path_parts(path):
    "Split a slash path into names"
    if isinstance(path, str): return [p for p in path.split('/') if p]
    return list(path)

def parent_at(root: TreeNode, path):
    "Return parent node and final name for path"
    *ps, name = _path_parts(path)
    return (root['/' + '/'.join(ps)] if ps else root), name

# %% ../nbs/01_tree.ipynb #5b1ff6cb
def rename(root: TreeNode, path, name: str):
    "Rename node at path in-place"
    p, old = parent_at(root, path)
    if name in p: raise KeyError(f"{name!r} already exists")
    p.children[p.idx(old)].name = name

# %% ../nbs/01_tree.ipynb #cc047ed5
def remove(root: TreeNode, path):
    "Remove node at path in-place and return it"
    p, name = parent_at(root, path)
    return p.children.pop(p.idx(name))

# %% ../nbs/01_tree.ipynb #177c29ba
def insert(root: TreeNode, parent, node: TreeNode, idx=None):
    "Insert node under parent in-place"
    p = root[parent]
    if node.name in p: raise KeyError(f"{node.name!r} already exists")
    p.children.insert(len(p.children) if idx is None else idx, node)

# %% ../nbs/01_tree.ipynb #39902c4c
def update(root: TreeNode, path, node: TreeNode):
    "Replace node at path in-place"
    p,name = parent_at(root, path)
    if node.name != name and node.name in p: raise KeyError(f"{node.name!r} already exists")
    p.children[p.idx(name)] = node

# %% ../nbs/01_tree.ipynb #cfd5dd49
def move(root: TreeNode, src, dst_parent, idx=None):
    "Move node from src to dst_parent in-place"
    sp, name = parent_at(root, src)
    node = sp.children[sp.idx(name)]
    dst = root[dst_parent]
    if node.name in dst: raise KeyError(f"{node.name!r} already exists")
    node = remove(root, src)
    insert(root, dst_parent, node, idx)

