_POST = object()

class TreeWalk(HasCallbacks):
    "Stack-based depth-first tree walker with callbacks"
    cbs_names = ('before_walk', 'after_walk', 'on_node_pre', 'on_node_post', 'on_leaf')
    def __init__(self, root: TreeNode, cbs=()): self.root=root; super().__init__(cbs=cbs)
    def __iter__(self):
        self.callback('before_walk')
        stack = [('', self.root, 0, 0, 1, None)]
        while stack:
            parent, n, depth, idx, n_sibs, tag = stack.pop()
            p = n.path(parent)
            ctx = AD(path=p, depth=depth, idx=idx, n_sibs=n_sibs, is_last=idx==n_sibs-1, is_leaf=n.is_leaf())
            if tag is _POST: self.callback('on_node_post', p, n, ctx)
            else:
                self.callback('on_node_pre', p, n, ctx)
                if n.is_leaf(): self.callback('on_leaf', p, n, ctx)
                stack.append((parent, n, depth, idx, n_sibs, _POST))
                for i,c in reversed(list(enumerate(n.children))): stack.append((p, c, depth+1, i, len(n.children), None))
                yield p, n, ctx
        self.callback('after_walk')

# %% ../nbs/01_tree.ipynb #a90bbd30
def visit(root: TreeNode, on_node_pre: Callable=None, on_node_post: Callable=None, on_leaf: Callable=None):
    "Depth-first walk calling callbacks for side effects"
    cbs = [CBs(**{k:v for k,v in dict(on_node_pre=on_node_pre, on_node_post=on_node_post, on_leaf=on_leaf).items() if v})]
    for _ in TreeWalk(root, cbs=cbs): pass

# %% ../nbs/01_tree.ipynb #55189f41
def transform(root: TreeNode, on_node: Callable=None) -> TreeNode:
    "Depth-first structural transform"
    stack, cur = [], []
    def _pre(ctx, p, n, c): stack.append(cur.copy()); cur.clear()
    def _post(ctx, p, n, c):
        children = list(cur)
        r = TreeNode(n.name, children, n.value, **n.meta)
        if on_node:
            o = on_node(p, r, n)
            if o is _SKIP: r = _SKIP
            elif o is not None: r = o
        cur.clear(); cur.extend(stack.pop())
        if r is not _SKIP: cur.append(r)
    visit(root, on_node_pre=_pre, on_node_post=_post)
    return cur[0]

# %% ../nbs/01_tree.ipynb #cf8544f3
def filter_nodes(root: TreeNode, pred: Callable) -> TreeNode:
    "Keep matching nodes, preserving original branches"
    return transform(root, lambda p,n,o: n if pred(o) or not o.is_leaf() or p=='/' else _SKIP)

def prune(root: TreeNode, pred: Callable) -> TreeNode:
    "Keep matching nodes and non-empty ancestors"
    return transform(root, lambda p,n,o: n if pred(o) or n.children or p=='/' else _SKIP)

# %% ../nbs/01_tree.ipynb #6043024e
def map_nodes(root: TreeNode, f: Callable) -> TreeNode:
    "Return new tree with f applied to every rebuilt node"
    return transform(root, lambda p,n,o: f(n))

# %% ../nbs/01_tree.ipynb #2f5a32fe
def map_values(root: TreeNode, f: Callable) -> TreeNode:
    "Return new tree with f applied to every node value"
    return map_nodes(root, lambda n: TreeNode(n.name, n.children, f(n.value), **n.meta))

def map_names(root: TreeNode, f: Callable) -> TreeNode:
    "Return new tree with f applied to every node name"
    return map_nodes(root, lambda n: TreeNode(f(n.name), n.children, n.value, **n.meta))

def map_meta(root: TreeNode, f: Callable) -> TreeNode:
    "Return new tree with f applied to every node meta"
    return map_nodes(root, lambda n: TreeNode(n.name, n.children, n.value, **f(n.meta)))

