def paths(root: TreeNode): return [p for p,_,_ in TreeWalk(root)]

# %% ../nbs/01_tree.ipynb #e737001c
def values(root: TreeNode): return [n.value for _,n,_ in TreeWalk(root)]
def items(root: TreeNode): return [(p,n) for p,n,_ in TreeWalk(root)]
def nodes(root: TreeNode): return [n for _,n,_ in TreeWalk(root)]
def leaves(root: TreeNode): return [n for _,n,c in TreeWalk(root) if c.is_leaf]
def branches(root: TreeNode): return [n for _,n,c in TreeWalk(root) if not c.is_leaf]
def height(root: TreeNode): return max((c.depth for _,_,c in TreeWalk(root)), default=0)
def count(root: TreeNode, leaves_only=False):
    "Count nodes"
    return sum(1 for _,_,c in TreeWalk(root) if not leaves_only or c.is_leaf)

# %% ../nbs/01_tree.ipynb #25e7a498
def reduce_nodes(root: TreeNode, f: Callable, init=None):
    "Reduce nodes left-to-right with f(acc, path, node, ctx)"
    acc = init
    for p,n,c in TreeWalk(root): acc = f(acc, p, n, c)
    return acc

