def find(root: TreeNode, pred: Callable, default=None):
    "Find first node matching pred"
    for p,n,c in TreeWalk(root):
        if pred(n): return p,n
    return default

def find_all(root: TreeNode, pred: Callable):
    "Find all nodes matching pred"
    return [(p,n) for p,n,_ in TreeWalk(root) if pred(n)]

search = find_all

def find_values(root: TreeNode, pred: Callable):
    "Find all nodes whose value matches pred"
    return find_all(root, lambda n: pred(n.value))

