def from_dict(d: Mapping, root='') -> TreeNode:
    "Convert a mapping tree to TreeNode"
    def _node(nm, v):
        if isinstance(v, Mapping): return TreeNode(str(nm), [_node(k, vv) for k,vv in v.items()])
        if is_listy(v): return TreeNode(str(nm), [_node(str(i), o) for i,o in enumerate(v)])
        return TreeNode(str(nm), value=v)
    return TreeNode(root, [_node(k, v) for k,v in d.items()])

def to_dict(root: TreeNode):
    "Convert TreeNode to nested dict/list/scalars"
    def _val(n):
        if n.is_leaf(): return n.value
        if all(o.name.isdigit() for o in n.children):
            xs = sorted(n.children, key=lambda o: int(o.name))
            if [int(o.name) for o in xs] == list(range(len(xs))): return [_val(o) for o in xs]
        return {o.name: _val(o) for o in n.children}
    return {o.name: _val(o) for o in root.children}

