def validate(root: TreeNode):
    "Validate TreeNode invariants recursively"
    if not isinstance(root.name, str): raise TypeError("name must be a str")
    if '/' in root.name: raise ValueError("name cannot contain '/'")
    if not all(isinstance(o, TreeNode) for o in root.children): raise TypeError("children must be TreeNodes")
    ns = [o.name for o in root.children]
    if len(ns) != len(set(ns)): raise ValueError("sibling names must be unique")
    for o in root.children: validate(o)
    return root

