@patch
def tree(self:Path, file_type:str=None, file_exts:list=None, exclude:list=None, hidden:bool=False, max_level:int=None) -> TreeNode:
    "Return a TreeNode rooted at path"
    import mimetypes
    root = self.resolve()
    extns = L(file_exts)
    if file_type: extns += L(k for k,v in mimetypes.types_map.items() if v.startswith(file_type+'/'))
    has_extns, exclude = len(extns)==0, set(exclude or [])
    def _kids(p, lvl=0):
        if max_level is not None and lvl >= max_level: return []
        res = []
        for o in sorted(p.iterdir(), key=_gett):
            if o.name in exclude or (not hidden and o.name.startswith('.')): continue
            if o.is_dir(): res.append(TreeNode(o.name, _kids(o, lvl+1), value=o, kind='dir'))
            elif has_extns or o.suffix in extns: res.append(TreeNode(o.name, value=o, kind='file'))
        return res
    return TreeNode(root.name or str(root), _kids(root), value=root, kind='dir')

