def folder_href(p): return f"/?at={quote(str(p.resolve().relative_to(base)), safe='')}"

def solveit_node(p,n):
    v = n.value
    if isinstance(v, Path) and n.meta.get('kind')=='dir': return A(path_nm(n, False), href=folder_href(v), target='_blank')
    return path_nm(n, False)
